    this._loaded = true;
    const body = doc.body;
    body.appendChild(this.dom);
    body.appendChild(this.bgEl);

    if (host.Platform.isMobileApp) {
      this._showPhone(position);
    } else {
      this._placeDesktop(position, win);
    }

