  const top = r.top + el.clientTop;
  const width = el.clientWidth;
  const height = el.clientHeight;
  return {
    left, top, width, height,
    cx: left + width / 2, cy: top + height / 2,
    minX: -width / 2, minY: -height / 2, maxX: width / 2, maxY: height / 2,
  };
