      const hay = (c.title + " " + c.url).toLowerCase();
      const matches = env().Ly([lower], hay);
      if (!matches) continue;
      s.matches = matches;
      s.score = env().xy(matches, lower.length, hay.length, 0);
      if (c.url.toLowerCase() === lower) typed = true;
      out.push(s);
