async function ng32FontAvailable(name) {
  if (name === "") return true;
  const fonts = document.fonts;
  if (!fonts) return false;
  await fonts.ready;
  return fonts.check(`12px "${name}"`);
}

function ng32AppContainer(hostEl) {
  this.appContainerEl = hostEl.createDiv("app-container");
  this.horizontalMainContainerEl = this.appContainerEl.createDiv("horizontal-main-container");
  this.workspaceEl = this.horizontalMainContainerEl.createDiv("workspace");
  this.statusBarEl = this.appContainerEl.createDiv("status-bar");
}

// ---- n-g32-feedback-gate.js ----
// g32 clean-room: policy gates for the mobile feedback banner.

const NG32_MIN_FILES = 50;
const NG32_MIN_AGE_MS = 15552e6;

async function ng32FeedbackShouldShow(app, host) {
  if (host.s16DevBuild) return true;
  if (!navigator.onLine) return false;
  if (localStorage.getItem(ng32MobileFeedbackFlag)) return false;
  const licensed = host.s16License.license
    || app.internalPlugins.getEnabledPluginById("sync")?.getRemoteVaultId();
  if (!licensed) return false;
  if (host.Platform.isIosApp && !(await host.capacitorApp.isInstalledFromStore())) return false;
  if (app.vault.getRoot().getFileCount() < NG32_MIN_FILES) return false;
  const stat = await app.vault.adapter.stat(app.vault.configDir);
  return Date.now() - stat.ctime >= NG32_MIN_AGE_MS;
}

// ---- n-g32-feedback.js ----
// g32 clean-room: "rate the app" banner for the mobile settings window.

function ng32DefineFeedbackBanner(host) {
  function Ng32FeedbackBanner(app, parentEl) {
    this.app = app;
    this.containerEl = parentEl.createDiv({ cls: "feedback-banner-container" });
    this.containerEl.hide();
    this.bannerEl = this.containerEl.createDiv("feedback-banner");
    this.bannerEl.createDiv({ cls: "feedback-banner-title", text: host.i18n.interface.mobile.feedback.labelFeedback() });
    const content = this.bannerEl.createDiv("feedback-banner-content");
    content.createDiv({ cls: "feedback-banner-body", text: host.i18n.interface.mobile.feedback.labelFeedbackDesc() });
    content.createEl("button", { text: host.i18n.interface.mobile.feedback.actionRate() })
      .addEventListener("click", () => this.submitRating());
    content.createDiv({ cls: "feedback-banner-dismiss-button", text: host.i18n.interface.mobile.feedback.actionDismiss() })
      .addEventListener("click", () => {
        localStorage.setItem(ng32MobileFeedbackFlag, "1");
        this.hide();
      });
  }

  Ng32FeedbackBanner.prototype.shouldShow = function () {
    return ng32FeedbackShouldShow(this.app, host);
  };

  Ng32FeedbackBanner.prototype.show = async function () {
    if (await this.shouldShow()) this.containerEl.show();
  };

  Ng32FeedbackBanner.prototype.hide = async function () {
    const height = this.containerEl.offsetHeight || 0;
    this.containerEl.style.height = `${height}px`;
    const spec = new host.Transition({ duration: 150, fn: "cubic-bezier(0.45,0.05,0.55,0.95)" });
    spec.addProp("height", `${height}px`, "0px", "")
      .addProp("opacity", "1", "0", "")
      .addProp("transform", "scaleY(1)", "scaleY(0)", "");
    runTransition(this.bannerEl, spec, () => {});
    await host.sleep(70);
    await ng15AnimateCollapse(this.containerEl);
    this.containerEl.hide();
  };

  Ng32FeedbackBanner.prototype.submitRating = async function () {
    localStorage.setItem(ng32MobileFeedbackFlag, "1");
    await host.s16ReviewApi.requestReview();
    await host.sleep(400);
    await this.hide();
  };

  return Ng32FeedbackBanner;
}

// ---- n-g32-font-modal.js ----
// g32 clean-room: ordered custom interface-font list editor.

function ng32RemoveFont(list, name) {
  if (typeof list.remove === "function") list.remove(name);
  else {
    const at = list.indexOf(name);
    if (at >= 0) list.splice(at, 1);
  }
}

function ng32DefineFontListModal(host) {
  const Base = host.ButtonModal;
  const fontT = () => host.i18n.setting.appearance;

  function Ng32FontListModal(app, title, values, callback) {
    const self = Base.call(this, app) || this;
    self.setTitle(title);
    self.app = app;
    self.values = values;
    self.callback = callback;
    self.descEl = self.contentEl.createDiv();
    self.fontListEl = self.contentEl.createDiv("setting-font-list");
    self.textInputEl = null;
    self.fontWarningEl = null;
    self.fontSuggest = null;

    new host.Setting(self.contentEl)
      .setName(fontT().labelFontName())
      .addExtraButton((button) => button
        .setIcon("lucide-alert-circle")
        .setTooltip(fontT().msgFontNotFound())
        .then((component) => {
          self.fontWarningEl = component.extraSettingsEl;
          component.extraSettingsEl.addClass("mod-warning");
          component.extraSettingsEl.hide();
        }))
      .addText((text) => {
        self.textInputEl = text.inputEl;
        text.setPlaceholder(fontT().optionFontPlaceholder());
        text.onChange(async (value) => {
          const available = await ng32FontAvailable(value);
          if (self.fontWarningEl) self.fontWarningEl.toggle(!available);
        });
        self.textInputEl.addEventListener("focus", () => {
          self.modalEl.style.transition = "unset";
          host.nextFrame(() => { self.modalEl.style.transition = ""; });
          if (!self.fontSuggest) {
            self.fontSuggest = new host.s16FontSuggest(app, self.textInputEl);
            self.fontSuggest.onSelect((value, event) => {
              self.addCurrent();
              if (event instanceof MouseEvent) self.textInputEl.blur();
            });
            ng32FontProbeDone.then(() => self.fontSuggest.onInputChange());
          }
        });
        self.textInputEl.addEventListener("keydown", (event) => {
          if (!event.isComposing && event.key === "Enter") self.addCurrent();
        });
      })
      .addButton((button) => button
        .setButtonText(host.i18n.interface.buttonAdd())
        .onClick(() => self.addCurrent()));

    self.addButton("mod-cta", host.i18n.dialogue.buttonSave(), () => {
      self.close();
      callback(self.values);
    });
    self.addCancelButton();
    return self;
  }
  inherit(Ng32FontListModal, Base);
  const proto = Ng32FontListModal.prototype;

  proto.onOpen = function () { this.display(); };

  proto.addCurrent = function () {
    const value = this.textInputEl ? this.textInputEl.value : "";
    if (value && !(typeof this.values.contains === "function" ? this.values.contains(value) : this.values.includes(value))) {
      this.values.push(value);
      this.display();
    }
    if (this.textInputEl) this.textInputEl.value = "";
    if (this.fontWarningEl) this.fontWarningEl.hide();
  };

  proto.display = function () {
    const self = this;
    const values = this.values;
    this.descEl.setText(values.length === 0 ? fontT().labelNoCustomFontSet() : fontT().labelFontApplied());
    this.fontListEl.empty();
    const render = (name) => {
      this.fontListEl.createDiv("mobile-option-setting-item", (row) => {
        row.createSpan({ cls: "mobile-option-setting-item-name", text: name }).style.fontFamily = name;
        const badge = row.createSpan("mobile-option-setting-item-option-icon");
        ng32FontAvailable(name).then((available) => {
          if (available) {
            badge.addClass("mod-success");
            host.setIcon(badge, "lucide-check-circle-2");
            host.setTooltip(badge, fontT().msgFontFound());
          } else {
            badge.addClass("mod-warning");
            host.setIcon(badge, "lucide-alert-circle");
            host.setTooltip(badge, fontT().msgFontNotFound());
          }
        });
        row.createDiv("clickable-icon mobile-option-setting-item-option-icon", (remove) => {
          host.setIcon(remove, "lucide-x");
          host.setTooltip(remove, host.i18n.interface.deleteActionShortName());
          remove.addEventListener("click", () => {
            ng32RemoveFont(values, name);
            self.display();
          });
        });
        row.createDiv("clickable-icon mobile-option-setting-item-option-icon mobile-option-setting-drag-icon", (handle) => {
          host.setIcon(handle, "lucide-menu");
          host.setTooltip(handle, host.i18n.interface.dragToRearrange());
          host.makeDragReorderable(row, row, self.fontListEl, 5, () => null, (to) => {
            ng32RemoveFont(values, name);
            values.splice(to, 0, name);
            self.display();
          });
        });
      });
    };
    for (const name of values) render(name);
  };

  return Ng32FontListModal;
}

// ---- n-g32-font-probe.js ----
// g32 clean-room: installed-font probe feeding the font suggest cache.

const ng32FontCache = ["Inter", "Source Code Pro"];
let ng32FontProbeDone = null;
const ng32FontSample = "abcdefghijklmnopqrstuvwxyz0123456789";
let ng32FontProbeStarted = false;

async function ng32ProbeFontNames(names, ctx, baseWidth) {
  let count = 0;
  for (const name of names) {
    if (ng32FontProbeSeen.has(name)) continue;
    ng32FontProbeSeen.add(name);
    ctx.font = `72px ${name}, monospace`;
    if (ctx.measureText(ng32FontSample).width !== baseWidth) ng32FontCache.push(name);
    if (++count % 10 === 0) await new Promise((resolve) => idleOrTimeout(resolve, 0));
  }
}

function ng32StartFontProbe(host) {
  if (ng32FontProbeStarted) return ng32FontProbeDone;
  ng32FontProbeStarted = true;
  ng32FontProbeDone = (async () => {
    const ctx = document.createElement("canvas").getContext("2d");
    if (!ctx) {
      ng32FontCache.sort();
      return;
    }
    ctx.font = "72px monospace";
    const baseWidth = ctx.measureText(ng32FontSample).width;
    const tasks = [];
    if (host.Platform.isDesktopApp) {
      tasks.push((async () => {
        try {
          const fonts = await host.electronBridge("get-fonts").getFonts();
          await ng32ProbeFontNames(fonts || [], ctx, baseWidth);
        } catch (error) { /* probe source unavailable */ }
      })());
    }
    if (host.Platform.isMobileApp) {
      tasks.push((async () => {
        try {
          const result = await host.capacitorApp.getFonts();
          await ng32ProbeFontNames((result && result.fonts) || [], ctx, baseWidth);
        } catch (error) { /* probe source unavailable */ }
      })());
    }
    tasks.push(ng32ProbeFontNames(ng32SystemFontList, ctx, baseWidth));
    await Promise.all(tasks);
    ng32FontCache.sort();
  })();
  return ng32FontProbeDone;
}

function ng32FontNames(host) {
  ng32StartFontProbe(host);
  return ng32FontCache;
}

// ---- n-g32-font-suggest.js ----
// g32 clean-room: font-family input suggest backed by the probe cache.

function ng32DefineFontSuggest(host) {
  function Ng32FontSuggest(app, textInputEl) {
    const self = host.AbstractInputSuggest.call(this, app, textInputEl) || this;
    self.app = app;
    self.textInputEl = textInputEl;
    self.fonts = () => ng32FontNames(host);
    return self;
  }
  inherit(Ng32FontSuggest, host.AbstractInputSuggest);
  const proto = Ng32FontSuggest.prototype;

  proto.renderSuggestion = function (text, el) {
    el.setText(text);
    el.style.fontFamily = text;
  };

  proto.getSuggestions = function (query) {
    const needle = (query || "").toLowerCase();
    const out = [];
    if (!needle) out.push("Inter");
    for (const name of this.fonts()) {
      if (name.toLowerCase().includes(needle)) out.push(name);
    }
    return out;
  };

  proto.selectSuggestion = function (text, event) {
    this.setValue(text);
    if (this.textInputEl.trigger) this.textInputEl.trigger("input");
    else this.textInputEl.dispatchEvent(new Event("input"));
    this.close();
    return host.AbstractInputSuggest.prototype.selectSuggestion.call(this, text, event);
  };

  return Ng32FontSuggest;
}

// ---- n-g32-mobile.js ----
// g32 clean-room: mobile toolbar settings tab + pull-down quick-action picker.

function ng32ListContains(list, id) {
  return typeof list.contains === "function" ? list.contains(id) : list.includes(id);
}
function ng32ListRemove(list, id) {
  if (typeof list.remove === "function") list.remove(id);
  else {
    const at = list.indexOf(id);
    if (at >= 0) list.splice(at, 1);
  }
}

function ng32DefineQuickActionSuggest(host) {
  function Ng32QuickActionSuggest(app, callback) {
    const self = host.FuzzySuggestModal.call(this, app) || this;
    self.emptyStateText = host.i18n.plugins.commandPalette.labelNoCommands();
    self.callback = callback;
    self.setPlaceholder(host.i18n.setting.mobileToolbar.placeholderSelectQuickAction());
    return self;
  }
  inherit(Ng32QuickActionSuggest, host.FuzzySuggestModal);
  const proto = Ng32QuickActionSuggest.prototype;

  proto.getItems = function () {
    return [null].concat(Object.values(this.app.commands.commands));
  };

  proto.getItemText = function (item) {
    return item ? item.name : host.i18n.setting.mobileToolbar.quickActionDisabled();
  };

  proto.onChooseItem = function (item) {
    this.app.vault.setConfig("mobilePullAction", item ? item.id : "");
    if (this.callback) this.callback();
  };

  return Ng32QuickActionSuggest;
}

function ng32DefineMobileToolbarTab(host) {
  const Base = host.SettingTab;
  const toolbarT = () => host.i18n.setting.mobileToolbar;

  function Ng32MobileToolbarTab(app, plugin) {
    const self = Base.call(this, app, plugin) || this;
    self.name = toolbarT().name();
    self.id = "mobile";
    self.icon = "wrench";
    app.commands.addCommand({
      id: "mobile:quick-action",
      name: toolbarT().optionConfigureQuickAction(),
      icon: "lucide-terminal-square",
      checkCallback: (checking) => {
        if (!host.Platform.isMobile) return false;
        if (!checking) new host.s16QuickActionModal(app).open();
        return true;
      },
    });
    return self;
  }
  inherit(Ng32MobileToolbarTab, Base);
  const proto = Ng32MobileToolbarTab.prototype;

  proto.display = function () {
    const self = this;
    const app = this.app;
    this.containerEl.empty();
    const allCommands = app.commands.commands;
    const editorCommands = app.commands.editorCommands;
    const pullAction = app.vault.getConfig("mobilePullAction");
    const pullCommand = app.commands.findCommand(pullAction);
    let toolbarCommands = app.vault.getConfig("mobileToolbarCommands") || [];

    const persist = () => {
      app.vault.setConfig("mobileToolbarCommands", toolbarCommands);
      self.display();
    };

    new host.SettingGroup(this.containerEl).addSetting((setting) => setting
      .setName(toolbarT().optionConfigureQuickAction())
      .setDesc(toolbarT().optionConfigureQuickActionDescription({ command: pullCommand ? pullCommand.name : toolbarT().quickActionDisabled() }))
      .addButton((button) => button
        .setButtonText(toolbarT().buttonConfigure())
        .onClick(() => new host.s16QuickActionModal(app, () => self.display()).open())));

    const enabledGroup = new host.SettingGroup(this.containerEl);
    if (toolbarCommands && toolbarCommands.length) {
      enabledGroup.setHeading(toolbarT().manageToolbarOptions());
      const listEl = enabledGroup.listEl.createDiv();
      toolbarCommands = toolbarCommands.filter((id) => allCommands[id]);
      for (const id of toolbarCommands) {
        const command = allCommands[id];
        listEl.createDiv("mobile-option-setting-item", (row) => {
          row.createSpan("mobile-option-setting-item-remove-icon", (icon) => {
            host.setIcon(icon, "lucide-minus-circle");
            icon.addEventListener("click", () => {
              if (ng32ListContains(toolbarCommands, id)) {
                ng32ListRemove(toolbarCommands, id);
                persist();
              }
            });
          });
          row.createSpan("mobile-option-setting-item-option-icon", (icon) => host.setIcon(icon, command.icon || "question-mark-glyph"));
          row.createSpan({ cls: "mobile-option-setting-item-name", text: command.name });
          row.createDiv("clickable-icon mobile-option-setting-item-option-icon mobile-option-setting-drag-icon", (handle) => {
            host.setIcon(handle, "lucide-menu");
            host.setTooltip(handle, host.i18n.interface.dragToRearrange());
            host.makeDragReorderable(handle, row, listEl, 5, () => null, (to) => {
              ng32ListRemove(toolbarCommands, id);
              toolbarCommands.splice(to, 0, id);
              persist();
            });
          });
        });
      }
    }

    const addable = Object.keys(editorCommands).filter((id) => !ng32ListContains(toolbarCommands, id));
    if (addable.length) {
      const moreGroup = new host.SettingGroup(this.containerEl);
      moreGroup.setHeading(toolbarT().optionMoreToolbarOptions());
      for (const id of addable) {
        const command = allCommands[id];
        moreGroup.listEl.createDiv("mobile-option-setting-item", (row) => {
          row.createSpan("mobile-option-setting-item-add-icon", (icon) => {
            host.setIcon(icon, "lucide-plus-circle");
            icon.addEventListener("click", () => {
              if (!ng32ListContains(toolbarCommands, id)) {
                toolbarCommands.push(id);
                persist();
              }
            });
          });
          row.createSpan("mobile-option-setting-item-option-icon", (icon) => host.setIcon(icon, command.icon || "question-mark-glyph"));
          row.createSpan({ text: command.name });
        });
      }
    }

    const searchable = Object.keys(allCommands)
      .filter((id) => !editorCommands[id] && !ng32ListContains(toolbarCommands, id))
      .map((id) => allCommands[id]);
    enabledGroup.addSearch((search) => search
      .setPlaceholder(host.i18n.plugins.commandPalette.promptTypeCommand())
      .then(() => new host.s16CommandSuggest(app, search.inputEl, searchable, (command) => {
        const id = command.id;
        if (!ng32ListContains(toolbarCommands, id)) {
          toolbarCommands.push(id);
          persist();
        }
      })));
  };

  return Ng32MobileToolbarTab;
}

// ---- n-g32-nav.js ----
// g32 clean-room: sync-sidebar tree items (base, folder, "+N more", file row).

let ng32NavBaseClass = null;

function ng32DefineNavItemBase(host) {
  if (ng32NavBaseClass) return ng32NavBaseClass;
  function Ng32NavItemBase() {
    const self = host.TreeItem.call(this) || this;
    self.info = { height: 0, width: 0, childLeft: 0, childLeftPadding: 0, childTop: 0, computed: false, queued: false, hidden: false, next: false };
    delete self.coverEl;
    return self;
  }
  inherit(Ng32NavItemBase, host.TreeItem);
  ng32NavBaseClass = Ng32NavItemBase;
  return Ng32NavItemBase;
}

function ng32DefineNavFolder(host) {
  const Base = host.s16TreeCollapsible(ng32DefineNavItemBase(host));
  function Ng32NavFolder(tree, id, title) {
    const self = Base.call(this, tree, id, title) || this;
    self.vChildren = new host.TreeChildren(self);
    self.pusherEl = host.s16TreePusher();
    self.tree = tree;
    self.id = id;
    self.setClickable(true);
    self.setCollapsible(true);
    self.el.addClass("nav-folder");
    self.selfEl.addClass("nav-folder-title");
    self.innerEl.addClass("nav-folder-title-content");
    self.childrenEl.addClass("nav-folder-children");
    self.innerEl.setText(title);
    self.flairEl = self.selfEl.createDiv("tree-item-flair-outer").createSpan("tree-item-flair");
    self.collapseEl.empty();
    return self;
  }
  inherit(Ng32NavFolder, Base);
  const proto = Ng32NavFolder.prototype;

  proto.clear = function () { this.vChildren.clear(); this.setFlair(0); };
  proto.addChild = function (child) { this.vChildren.addChild(child); };
  proto.onSelfClick = function () { this.toggleCollapsed(true); };
  proto.setFlair = function (count) { this.flairEl.setText(host.i18n.nouns.count({ count })); };
  proto.setCollapsed = function (collapsed, scroll) {
    return (async () => {
      await Base.prototype.setCollapsed.call(this, collapsed, scroll);
      this.tree.infinityScroll.invalidate(this);
      this.tree.requestSaveFolds();
    })();
  };
  return Ng32NavFolder;
}

function ng32DefineNavMoreButton(host) {
  const Base = ng32DefineNavItemBase(host);
  function Ng32NavMoreButton(parent, count) {
    const self = Base.call(this, parent, count) || this;
    self.parent = parent;
    self.count = count;
    self.setClickable(false);
    self.el.addClass("nav-file");
    self.selfEl.addClass("more-button");
    self.innerEl.addClass("nav-file-title-content");
    self.innerEl.setText(host.i18n.plugins.sync.labelMore({ count }));
    return self;
  }
  inherit(Ng32NavMoreButton, Base);
  return Ng32NavMoreButton;
}

function ng32DefineSyncNavFile(host) {
  const Base = ng32DefineNavItemBase(host);
  function Ng32SyncNavFile(view, sFile) {
    const self = Base.call(this, view, sFile) || this;
    self.view = view;
    self.sFile = sFile;
    self.setClickable(true);
    self.el.addClass("nav-file");
    self.selfEl.addClass("nav-file-title");
    self.innerEl.addClass("nav-file-title-content");
    const ext = extensionOf(sFile.path);
    if (!host.markdownExtensions.contains(ext)) self.selfEl.createDiv({ cls: "nav-file-tag", text: ext });
    self.innerEl.setText(baseName(sFile.path));
    self.selfEl.setAttr("data-path", sFile.path);
    self.selfEl.addEventListener("mouseover", (event) => self.onFileMouseover(event));
    self.selfEl.addEventListener("mouseout", (event) => self.onFileMouseout(event));
    self.selfEl.addEventListener("contextmenu", (event) => self.openFileContextMenu(event));
    return self;
  }
  inherit(Ng32SyncNavFile, Base);
  const proto = Ng32SyncNavFile.prototype;

  proto.onSelfClick = function (event) {
    this.view.app.workspace.openLinkText(this.sFile.path, "", host.Keymap.isModEvent(event));
  };

  proto.openFileContextMenu = function (event) {
    event.preventDefault();
    const dest = this.view.app.metadataCache.getFirstLinkpathDest(this.sFile.path, "");
    if (!dest) return;
    const menu = new host.Menu().addSections(["title", "open", "action", "view", "info", "", "danger"]);
    menu.addItem((item) => item
      .setSection("view")
      .setTitle(host.i18n.plugins.sync.menuOptViewVersionHistory())
      .setIcon("lucide-history")
      .onClick(() => this.view.sync.showVersionHistory(this.sFile.path)));
    this.view.app.workspace.trigger("file-menu", menu, dest, "sync-sidebar");
    menu.showAtMouseEvent(event);
  };

  proto.onFileMouseover = function (event) {
    if (!host.pointerEntered(event, this.selfEl) || host.isTouchSyntheticMouse(event)) return;
    let text = window.moment(this.sFile.mtime).format("llll");
    if (this.sFile.user && Object.prototype.hasOwnProperty.call(this.view.userMap, this.sFile.user)) text += "\n" + this.view.userMap[this.sFile.user];
    host.displayTooltip(this.selfEl, text, {
      placement: this.view.getSideTooltipPlacement(),
      gap: 24,
      horizontalParent: this.view.containerEl,
      delay: host.s16NavTooltipDelay,
    });
  };

  proto.onFileMouseout = function (event) {
    if (host.pointerEntered(event, this.selfEl)) host.hideTooltip();
  };

  return Ng32SyncNavFile;
}

