// Markdown-files-only file suggest.
function ng34DefineMarkdownFileSuggest(host) {
  return class Ng34MarkdownFileSuggest extends host.FilePathSuggest {
    filePredicate(file) {
      return file.extension === "md";
    }
  };
}

// File suggest filtered by an arbitrary predicate.
function ng34DefinePredicatedFileSuggest(host) {
  return class Ng34PredicatedFileSuggest extends host.FilePathSuggest {
    constructor(app, textInputEl, predicate, ...rest) {
      super(app, textInputEl, ...rest);
      this.predicate = predicate;
    }
    filePredicate(file) {
      return !this.predicate || this.predicate(file);
    }
  };
}

// Folder suggest filtered by an arbitrary predicate; the FolderSuggest base
// reuses the filePredicate hook for its candidates.
function ng34DefinePredicatedFolderSuggest(host) {
  return class Ng34PredicatedFolderSuggest extends host.FolderSuggest {
    constructor(app, textInputEl, folderPredicate, allowNullSelection = false) {
      super(app, textInputEl, allowNullSelection);
      this.folderPredicate = folderPredicate;
    }
    filePredicate(folder) {
      return !this.folderPredicate || this.folderPredicate(folder);
    }
  };
}

// ---- n-g34-rename-links.js ----
// g34 clean-room: link-rewriting rename base plus heading and block-id
// rename modals (spec g34 part F, second half).

// Shared base: collects link updates, rewrites the renamed file's own
// references through vault.process, everything else via metadataCache.
function ng34DefineRenameLinkModal(host) {
  return class Ng34RenameLinkModal extends host.TextInputModal {
    constructor(app, editor, file, tokenRange, initialValue) {
      super(app, initialValue);
      this.editor = editor;
      this.file = file;
      this.tokenRange = tokenRange;
    }

    async submit(value) {
      const error = this.validate(value);
      if (error) {
        this.displayError(error, false);
        return true;
      }
      const changes = this.getChanges(value);
      const fileCount = changes.data.size;
      const linkCount = changes.count();
      if (linkCount !== 0) {
        const own = changes.get(this.file.path);
        if (own && own.length > 0) {
          changes.clear(this.file.path);
          const replacement = this.replaceInFile(value);
          own.push({
            sourcePath: this.file.path,
            change: replacement.text,
            reference: {
              link: "",
              original: "",
              position: {
                start: { line: 0, col: 0, offset: replacement.start },
                end: { line: 0, col: 0, offset: replacement.end },
              },
            },
          });
          await this.app.vault.process(this.file, (content) => applyLinkUpdates(content, own));
        } else {
          this.replaceInEditor(value);
        }
        await this.app.metadataCache.updateInternalLinks(changes);
        new host.Notice(host.t.dialogue.msgUpdatedLinks({
          links: host.t.nouns.linkWithCount({ count: linkCount }),
          files: host.t.nouns.fileWithCount({ count: fileCount }),
        }));
      } else {
        this.replaceInEditor(value);
      }
      const custom = this.getCustomReplacements(value);
      for (const updater of Object.values(this.app.metadataCache.linkUpdaters)) {
        await updater.renameSubpath(this.file, custom.oldSubpath, custom.newSubpath);
      }
      this.close();
      return undefined;
    }
  };
}

// Iterates every link reference in the vault; `match(parsed)` decides
// whether the reference's subpath targets the renamed heading/block.
function ng34ScanRefs(modal, host, value, match, makeLink) {
  const changes = new RefMultimap();
  modal.app.metadataCache.iterateAllRefs((sourceFile, reference) => {
    const parsed = parseLinktext(reference.link);
    if (!parsed.subpath) return;
    if (!match(parsed)) return;
    if (modal.app.metadataCache.getFirstLinkpathDest(parsed.path, sourceFile) !== modal.file) return;
    changes.add(sourceFile, {
      sourcePath: sourceFile,
      reference,
      change: ng34RewriteLinkText(reference, makeLink(parsed, value), host),
    });
  });
  return changes;
}

function ng34DefineHeadingRenameModal(host) {
  const LinkBase = ng34DefineRenameLinkModal(host);
  return class Ng34HeadingRenameModal extends LinkBase {
    constructor(app, editor, file, tokenRange, oldHeading) {
      super(app, editor, file, tokenRange, oldHeading);
      this.oldHeading = oldHeading;
      this.title = host.t.dialogue.labelRenameHeading();
    }

    validate(value) {
      return value === "" ? host.t.dialogue.msgHeadingEmpty() : "";
    }

    getChanges(value) {
      const oldPlain = plainHeading(this.oldHeading).toLowerCase();
      return ng34ScanRefs(this, host, value,
        (parsed) => plainHeading(parsed.subpath.substring(1)).toLowerCase() === oldPlain,
        (parsed, v) => parsed.path + "#" + linkSafeHeading(v));
    }

    replaceInEditor(value) {
      const line = this.editor.offsetToPos(this.tokenRange.start).line;
      const text = this.editor.getLine(line);
      this.editor.setLine(line, this.replaceHeadingText(text, value));
    }

    replaceInFile(value) {
      const line = this.editor.offsetToPos(this.tokenRange.start).line;
      const text = this.editor.getLine(line);
      return { ...this.tokenRange, text: this.replaceHeadingText(text, value) };
    }

    replaceHeadingText(line, value) {
      return line.replace(/^(#{1,6} ).*/m, (m, marks) => marks + value);
    }

    getCustomReplacements(value) {
      return {
        oldSubpath: plainHeading(this.oldHeading).toLowerCase(),
        newSubpath: linkSafeHeading(value),
      };
    }
  };
}

function ng34DefineBlockIdRenameModal(host) {
  const LinkBase = ng34DefineRenameLinkModal(host);
  const wanted = (token) => ("#" + token.text).toLowerCase();
  return class Ng34BlockIdRenameModal extends LinkBase {
    constructor(app, editor, file, tokenRange, token) {
      super(app, editor, file, tokenRange, token.text.substring(1));
      this.token = token;
      this.title = host.t.dialogue.labelRenameBlockid();
    }

    validate(value) {
      if (value === "") return host.t.dialogue.msgBlockIdEmpty();
      return /^[a-zA-Z0-9\-]+$/.test(value) ? "" : host.t.dialogue.msgBlockIdInvalid();
    }

    getChanges(value) {
      const target = wanted(this.token);
      return ng34ScanRefs(this, host, value,
        (parsed) => parsed.subpath.toLowerCase() === target,
        (parsed, v) => parsed.path + "#^" + v);
    }

    replaceInEditor(value) {
      this.editor.replaceRange("^" + value, this.token.start, this.token.end);
    }

    replaceInFile(value) {
      return { ...this.tokenRange, text: "^" + value };
    }

    getCustomReplacements(value) {
      return { oldSubpath: this.token.text.toLowerCase(), newSubpath: "^" + value };
    }
  };
}

// ---- n-g34-rename.js ----
// g34 clean-room: rename modals — file rename, link-rewriting base,
// heading rename and block-id rename (spec g34 part F).

// File rename with name validation.
function ng34DefineFileRenameModal(host) {
  return class Ng34FileRenameModal extends host.TextInputModal {
    constructor(app, file) {
      super(app, file.basename);
      this.file = file;
      if (file.extension === "md") this.title = host.t.dialogue.labelRenameFile();
    }

    validate(value) {
      const error = super.validate(value);
      if (error) return error;
      const msgs = host.t.plugins.fileExplorer;
      if (value === "") return msgs.msgEmptyFileName();
      if (host.invalidCharsPattern.test(value)) return msgs.msgInvalidCharacters() + host.invalidCharsList;
      if (value.charAt(0) === ".") return msgs.msgBadDotfile();
      if (host.unsafeCharsPattern.test(value)) return msgs.msgUnsafeCharacters() + host.unsafeCharsList;
      if (this.app.vault.checkForDuplicate(this.file, value)) return msgs.msgFileAlreadyExists();
      return "";
    }

    async submit(value) {
      const error = this.validate(value);
      if (error) {
        this.displayError(error, false);
        return true;
      }
      this.close();
      const newPath = this.file.getNewPathAfterRename(value);
      if (this.file.path === newPath) return undefined;
      try {
        await this.app.fileManager.renameFile(this.file, newPath);
        new host.Notice(host.t.dialogue.msgRenameSuccess());
      } catch (err) {
        new host.Notice(err && (err.message || err.code) ? (err.message || err.code) : String(err));
        return true;
      }
      return undefined;
    }
  };
}

// ---- n-g34-render.js ----
// g34 clean-room: markdown-preview post-processing — element/source maps,
// section parsing, callout icon, link href extraction, mermaid rendering
// (spec g34 part J, first half).

// Element -> source text stores for the preview recycler.
const ng34MermaidTextMap = new WeakMap();
const ng34MathTextMap = new WeakMap();

// Source text of a code/math element, cached per element; one trailing
// newline is stripped.
function ng34CodeBlockText(el) {
  let text = ng34MermaidTextMap.get(el);
  if (text === undefined) {
    text = el.getText();
    if (text.charAt(text.length - 1) === "\n") text = text.slice(0, -1);
    ng34MermaidTextMap.set(el, text);
  }
  return text;
}

// First "language-*" class with the prefix intact; undefined when absent.
function ng34CodeLanguage(el) {
  const classes = String(el.className || "").split(/\s+/);
  for (const cls of classes) {
    if (cls.indexOf("language-") === 0) return cls;
  }
  return undefined;
}

function ng34EachSection(sections, selector, visit) {
  for (const section of sections) {
    const found = section.el.findAll(selector);
    for (let i = 0; i < found.length; i++) {
      if (visit(found[i])) return found[i];
    }
  }
  return null;
}

// First loaded code element matching language + cached source text.
function ng34FindCodeBlock(sections, language, text) {
  return ng34EachSection(sections, 'code[class*="language-"].is-loaded', (el) =>
    ng34CodeBlockText(el) === text && ng34CodeLanguage(el) === language);
}

// First loaded math element matching text and block/inline kind.
function ng34FindMath(sections, text, isBlock) {
  return ng34EachSection(sections, ".math.is-loaded", (el) =>
    ng34MathTextMap.get(el) === text && el.classList.contains("math-block") === isBlock);
}

// Attribute-wise equality over the given names (missing == missing).
function ng34SameAttributes(a, b, names) {
  for (const name of names) {
    if (a.getAttr(name) !== b.getAttr(name)) return false;
  }
  return true;
}

// First loaded internal embed matching src/width/height/alt.
function ng34FindInternalEmbed(sections, el) {
  return ng34EachSection(sections, ".internal-embed.is-loaded", (candidate) =>
    ng34SameAttributes(candidate, el, ["src", "width", "height", "alt"]));
}

function ng34IsImage(el) {
  return typeof HTMLImageElement !== "undefined" && el instanceof HTMLImageElement;
}

// First complete image with the same src; copies width/height/alt onto it.
function ng34FindImage(sections, img, source) {
  return ng34EachSection(sections, "img", (candidate) => {
    if (!ng34IsImage(candidate) || !candidate.complete || candidate.src !== source) return false;
    for (const name of ["width", "height", "alt"]) {
      const value = img.getAttribute(name);
      if (value !== null) candidate.setAttribute(name, value);
    }
    return true;
  });
}

// Renders a callout icon: quoted strings are unwrapped, "<svg" payloads are
// sanitised and inlined, anything else goes through the icon renderer.
function ng34RenderCalloutIcon(el, icon) {
  let name = icon;
  if (typeof icon === "string" && icon.length > 1) {
    if (icon.charAt(0) === "'" && icon.charAt(icon.length - 1) === "'") {
      name = icon.slice(1, -1).replace(/\\'/g, "'");
    } else if (icon.charAt(0) === '"') {
      try {
        const parsed = JSON.parse(icon);
        if (typeof parsed === "string") name = parsed;
      } catch (e) {
        // keep the raw text
      }
    }
  }
  if (typeof name === "string" && name.indexOf("<svg") === 0) {
    const holder = env().xL(name);
    const node = holder && holder.firstChild;
    if (typeof SVGSVGElement !== "undefined" && node instanceof SVGSVGElement) {
      node.setAttribute("width", "16");
      node.setAttribute("height", "16");
      node.setAttribute("fill", "currentColor");
      node.setAttribute("stroke", "currentColor");
      el.empty();
      el.appendChild(node);
      return;
    }
  }
  env().tv(el, name);
}

// Internal-link href of a rendered element belonging to the section.
function ng34InternalLinkHref(el, section) {
  const href = el.getAttr("data-href") || el.getAttr("href");
  return href && env().Gz.belongsToMe(el, section) ? href : null;
}

// First heading child element.
function ng34FirstHeading(el, cb) {
  const first = el.firstChild;
  if (first instanceof HTMLHeadingElement) cb(first);
}

// List items that contain a nested ul/ol.
function ng34NestedListItems(el, cb) {
  const items = el.findAll("li");
  for (let i = 0; i < items.length; i++) {
    if (items[i].findAll("ul,ol").length > 0) cb(items[i]);
  }
}

// Order-sensitive range equality via the app's Array.prototype.eq.
function ng34RangesEqual(a, b) {
  if (a.length === b.length) return a.eq(b);
  if (a.length < b.length) return b.slice(0, a.length).eq(a);
  return a.slice(0, b.length).eq(b);
}

// Splits markdown into per-top-level-node sections with relative data-line
// numbering; leaves the parse tree mutated (single-child children array).
function ng34ParseMarkdownSections(text) {
  const tree = env().Kx(text);
  const defs = { definitions: env().oT(tree) };
  const frontmatter = env().$x(tree);
  const children = tree.children || [];
  tree.children = [null];
  const sections = [];
  for (const node of children) {
    const level = node.type === "heading" ? node.depth || 1 : 7;
    env().jC(node, ["checklist", "listItem", "code"], (child) => {
      if (!child.data) child.data = {};
      if (!child.data.hProperties) child.data.hProperties = {};
      child.data.hProperties["data-line"] = String(child.position.start.line - node.position.start.line);
    });
    tree.children[0] = node;
    sections.push({ html: env().Zx(tree, defs), pos: env().hT(node.position), level });
  }
  return { sections, frontmatter };
}

// First rendered mermaid block matching the cached source text.
function ng34FindMermaid(sections, text) {
  return ng34EachSection(sections, ".mermaid", (el) => ng34CodeBlockText(el) === text);
}

// ---- n-g35-bases-formula.js ----
// g35 clean-room: formula property renderer — value/error display and the
// formula editor menu (spec g35, s26-bases-values).

function ng35FormulaBase() {
  function Base(view, prop, el) {
    ng35ValueRendererBase.call(this, view, prop, el);
  }
  return Base;
}

/** Formula result renderer: renders value.renderTo or an error box. */
function ng35FormulaValueRenderer(host) {
  const Base = ng35FormulaBase();
  function FormulaValueRenderer(view, prop, el) {
    Base.call(this, view, prop, el);
    this.el.addClass("bases-rendered-value");
    this.value = null;
    this.error = null;
  }
  inherit(FormulaValueRenderer, Base);
  FormulaValueRenderer.prototype.render = async function (entry) {
    let value = null;
    let error = null;
    try {
      value = entry.getValue(this.prop);
    } catch (e) {
      error = e;
    }
    const sameError = (error && error.message) === (this.error && this.error.message);
    if (env().gW.equals(value, this.value) && sameError) return;
    this.value = value;
    this.error = error;
    this.el.empty();
    this.el.setAttribute("data-property-type", value ? s09ValueTypeName(value.type) : "");
    if (error) {
      this.renderError(error);
    } else if (value) {
      value.renderTo(this.el, this.view.app.renderContext);
    }
  };
  FormulaValueRenderer.prototype.renderError = function (error) {
    const box = this.el.createDiv("bases-formula-error");
    const icon = box.createDiv("warning-icon");
    host.setIcon(icon, "lucide-info");
    const msg = box.createDiv("bases-formula-error-message");
    msg.setText(error.message);
    const showTip = () => host.setTooltip && host.setTooltip(box, error.message, { delay: host.TOOLTIP_DELAY });
    if (host.setTooltip) showTip();
    box.addEventListener("click", showTip);
    box.addEventListener("dblclick", (e) => {
      e.preventDefault();
      this.showFormulaEditor();
    });
  };
  FormulaValueRenderer.prototype.showFormulaEditor = function () {
    const name = parsePropertyId(this.prop).name;
    const menu = new host.s13BasesMenu(this.view.app, this.el, name);
    const bar = menu.scrollEl.createDiv("bases-toolbar-menu-container");
    const header = bar.createDiv("bases-toolbar-menu-container-header");
    const title = header.createDiv("menu-title");
    title.createDiv("menu-title-inner").setText(env().gm.plugins.bases.titleEditProperty({ name }));
    const btn = header.createDiv("clickable-icon");
    host.setIcon(btn, "lucide-more-vertical");
    const actions = new host.s13PropActionsMenu(this.view.queryController, this.prop, false);
    bar.appendChild(actions.containerEl);
    btn.addEventListener("click", (e) => actions.showActions(e, btn));
    menu.setAutoDestroy(this.el);
    menu.onClose(() => this.view.focus());
    menu.setOpen(true);
  };
  return FormulaValueRenderer;
}

// ---- n-g35-bases-values.js ----
// g35 clean-room: Bases property value renderers — shared ctor base, the
// metadata-property widget, the file-link renderer and the formula renderer
// (spec g35, s26-bases-values).

/** Plain constructor base invoked via .call(this, view, prop, el). */
function ng35ValueRendererBase(view, prop, el) {
  this.view = view;
  this.prop = prop;
  this.el = el;
}

function ng35RendererBase(host) {
  function Base(view, prop, el) {
    ng35ValueRendererBase.call(this, view, prop, el);
  }
  return Base;
}

/** Metadata-property widget: re-renders only when type or raw value changes. */
function ng35MetadataValueRenderer(host) {
  const Base = ng35RendererBase(host);
  function MetadataValueRenderer(view, prop, el) {
    Base.call(this, view, prop, el);
    this.el.addClass("bases-rendered-value", "metadata-property-value");
    this.propertyEditor = null;
    this.inferredType = null;
  }
  inherit(MetadataValueRenderer, Base);
  MetadataValueRenderer.prototype.render = async function (entry) {
    const name = parsePropertyId(this.prop).name;
    const raw = entry.getRawProperty(name);
    const rawJson = JSON.stringify(raw);
    if (entry.file.extension !== "md") {
      this.propertyEditor = null;
      this.el.empty();
      this.el.setAttribute("disabled", "");
      return;
    }
    this.el.removeAttribute("disabled");
    const inferred = this.view.app.metadataTypeManager.getTypeInfo(name, raw).inferred;
    if (this.propertyEditor && this.inferredType === inferred && this.val === rawJson) return;
    this.el.empty();
    this.inferredType = inferred;
    this.val = rawJson;
    this.entry = entry;
    this.el.setAttribute("data-property-type", inferred.type);
    this.propertyEditor = inferred.render(this.el, raw, {
      app: this.view.app,
      key: name,
      hoverSource: "bases",
      sourcePath: entry.file.path,
      blur: () => {
        host.blurAndClearSelection();
        this.el.scrollLeft = 0;
        this.view.focus();
      },
      onChange: (value) => {
        const next = emptyToNull(value);
        const nextJson = JSON.stringify(next);
        if (nextJson === this.val) return;
        this.val = nextJson;
        this.view.updateProperty(entry.file, name, next);
      },
    });
  };
  return MetadataValueRenderer;
}

/** file.* renderer: the standard file-link chip, cached per file+path. */
function ng35FileValueRenderer(host) {
  const Base = ng35RendererBase(host);
  function FileValueRenderer(view, prop, el) {
    Base.call(this, view, prop, el);
    this.el.addClass("bases-rendered-value");
  }
  inherit(FileValueRenderer, Base);
  FileValueRenderer.prototype.render = async function (entry) {
    if (this.file === entry.file && this.filepath === entry.file.path) return;
    this.el.empty();
    this.entry = entry;
    this.file = entry.file;
    this.filepath = entry.file.path;
    this.view.app.renderContext.renderFileLink(entry.file, null, this.el);
  };
  return FileValueRenderer;
}

// ---- n-g35-bases-view.js ----
// g35 clean-room: BasesView — the abstract base every Bases view type derives
// from: frontmatter transactions with undo/redo, group headings, table export
// and clipboard copy (spec g35, s26-bases-view).

const ng35Json = (o) => JSON.stringify(o);

/** Bases view base class. ctor (queryController). */
function ng35BasesView(host) {
  function BasesView(queryController) {
    host.Component.call(this);
    this.allProperties = [];
    this.undoStack = [];
    this.redoStack = [];
    this.app = queryController.app;
    this.queryController = queryController;
  }
  inherit(BasesView, host.Component);
  const P = BasesView.prototype;

  P.getViewActions = function () { return []; };
  P.onResize = function () {};
  P.focus = function () {};
  P.setEphemeralState = function () {};
  P.getEphemeralState = function () { return {}; };
  P.createFileForView = function (file, extra) {
    return this.queryController.newItemMenu.open(file, extra);
  };

  // fn(changes) pushes {file, start, end}; a transaction commits only when at
  // least one change actually differs.
  P.createTransaction = async function (fn) {
    const transaction = { changes: [], state: this.getEphemeralState() };
    await fn(transaction.changes);
    const wrote = transaction.changes.some((c) => ng35Json(c.start) !== ng35Json(c.end));
    if (!wrote) return;
    this.queryController.requestNotifyView();
    this.redoStack = [];
    this.undoStack.push(transaction);
  };

  P.updateProperty = async function (file, prop, value) {
    const v = emptyToNull(value);
    await this.createTransaction(async (changes) => {
      await this.app.fileManager.processFrontMatter(file, (fm) => {
        const key = keyIgnoringCase(fm, prop);
        const exists = key !== prop || Object.hasOwn(fm, prop);
        if (!exists && v == null) return;
        const start = JSON.parse(ng35Json(fm));
        fm[exists ? key : prop] = v;
        changes.push({ file, start, end: fm });
      });
    });
  };

  // Undo/redo apply a change only while the live frontmatter still equals the
  // recorded opposite state, so concurrent edits are never clobbered.
  const restore = async function (view, from, to, matchKey, assignKey) {
    const t = view[from].pop();
    if (!t) return;
    view[to].push(t);
    view.setEphemeralState(t.state);
    for (const c of t.changes) {
      await view.app.fileManager.processFrontMatter(c.file, (fm) => {
        if (ng35Json(fm) === ng35Json(c[matchKey])) Object.assign(fm, c[assignKey]);
      });
    }
  };
  P.undoTransaction = function () { return restore(this, "undoStack", "redoStack", "end", "start"); };
  P.redoTransaction = function () { return restore(this, "redoStack", "undoStack", "start", "end"); };

  P.createGroupHeadingEl = function (group) {
    if (!group.key) return null;
    const el = env().createDiv("bases-group-heading");
    if (this.config && this.config.groupBy) {
      el.createDiv("bases-group-property").setText(this.config.getDisplayName(this.config.groupBy.property));
    }
    const valueEl = el.createDiv("bases-group-value");
    if (env().gW.equals(group.key, env().bW.value)) {
      valueEl.setText(env().gm.plugins.bases.labelGroupKeyNone());
    } else {
      group.key.renderTo(valueEl, this.app.renderContext);
    }
    return el;
  };

  P.exportTable = function () {
    const props = this.data.properties;
    const cell = (entry, prop) => {
      try {
        const v = entry.getValue(prop);
        if (v == null || env().gW.equals(v, env().bW.value)) return "";
        return v.toString();
      } catch (e) {
        return "";
      }
    };
    const header = props.map((p) => this.config.getDisplayName(p));
    const rows = this.data.data.map((entry) => props.map((p) => cell(entry, p)));
    return new host.s13TableExport(header, rows);
  };

  P.copyToClipboard = function () {
    const table = this.exportTable();
    const markdown = table.toMarkdown();
    const payload = {
      "text/plain": table.toTSV(),
      "text/markdown": markdown,
      "text/html": host.treeToHtml(host.markdownTree(markdown)),
      "basalt/table": table.toObsidianTableClipboard(),
    };
    const doc = env().activeDocument;
    const area = doc.createElement("textarea");
    area.value = payload["text/plain"] || Object.values(payload)[0];
    area.style.cssText = "position:fixed;top:0;left:0;opacity:0";
    doc.body.appendChild(area);
    const onCopy = (e) => {
      e.preventDefault();
      for (const type of Object.keys(payload)) e.clipboardData.setData(type, payload[type]);
    };
    doc.addEventListener("copy", onCopy, { once: true });
    area.focus();
    area.select();
    let ok = false;
    try {
      ok = doc.execCommand("copy");
    } catch (e) {
      console.error(e);
    }
    doc.removeEventListener("copy", onCopy);
    area.remove();
    const gm = env().gm.interface;
    new host.Notice(ok ? gm.copied({ context: "generic" }) : gm.copy_failed());
  };

  // Renderer registry: file.name -> file link, note.* -> metadata widget,
  // everything else -> formula.
  P.createRenderer = function (prop, el) {
    const type = prop === "file.name" ? "file" : parsePropertyId(prop).type === "note" ? "note" : "formula";
    const Cls = type === "file" ? env().f$ : type === "note" ? env().d$ : env().m$;
    return new Cls(this, prop, el);
  };

  return BasesView;
}

// ---- n-g35-chrome.js ----
// g35 clean-room: removable filter chip above the hotkey settings list and
// the status-filter id -> title map (spec g35, s29-chrome).

/** Filter chip widget: value + title + once-only remove callback. */
function ng35DefineHotkeyFilterChip(host) {
  function HotkeyFilterChip(containerEl) {
    this.value = null;
    this.handleRemove = null;
    this.el = createDiv({ cls: "hotkey-filter" });
    this.innerEl = this.el.createDiv({
      cls: "hotkey-filter-inner",
      text: host.t.setting.hotkeys.labelShowAll(),
    });
    this.removeEl = this.el.createDiv("hotkey-filter-remove-button");
    host.setIcon(this.removeEl, "lucide-x");
    host.setTooltip(this.removeEl, host.t.interface.menu.close());
    if (containerEl) containerEl.appendChild(this.el);
  }
  HotkeyFilterChip.prototype.setValue = function (v) { this.value = v; return this; };
  HotkeyFilterChip.prototype.setTitle = function (t) {
    this.innerEl.textContent = t;
    return this;
  };
  HotkeyFilterChip.prototype.onRemove = function (cb) {
    this.handleRemove = cb;
    this.removeEl.addEventListener("click", () => this.remove());
    return this;
  };
  HotkeyFilterChip.prototype.remove = function () {
    this.value = null;
    if (!this.el.isShown()) return;
    this.el.remove();
    if (this.handleRemove) this.handleRemove();
  };
  return HotkeyFilterChip;
}

/** Filter id -> i18n title function (functions, not evaluated strings). */
function ng35HotkeyFilterTitles(host) {
  const hk = host.t.setting.hotkeys;
  return {
    "show-all": hk.labelShowAll,
    "show-assigned": hk.labelShowAssigned,
    "show-user-assigned": hk.labelShowUserAssigned,
    "show-unassigned": hk.labelShowUnassigned,
  };
}

// ---- n-g35-debug-info.js ----
// g35 clean-room: debug-info modal — collects versions, theme/snippet/plugin
// state and upgrade recommendations into a read-only text area (spec g35,
// s29-debug-info). The report text format is contract.

const NG35_REC_INSTALLER = "\tUpdate installer: installer version too low, please download from ";
const NG35_REC_INSTALLER_TAIL = " and reinstall.\n";
const NG35_REC_THEME = "\tCustom theme and snippets: for cosmetic issues, please first try updating your theme and disabling your snippets. If still not fixed, please try to make the issue happen in the Sandbox Vault or disable community theme and snippets.\n";
const NG35_REC_PLUGINS = "\tCommunity plugins: for bugs, please first try updating all your plugins to latest. If still not fixed, please try to make the issue happen in the Sandbox Vault or disable community plugins.\n";

function ng35SnippetCount(customCss) {
  const snippets = customCss.snippets || [];
  const enabled = customCss.enabledSnippets;
  if (!enabled) return 0;
  const has = typeof enabled.has === "function" ? (s) => enabled.has(s) : (s) => enabled.includes(s);
  return snippets.filter(has).length;
}

/** Debug info modal. ctor (app); extends host.ButtonModal. */
function ng35DefineDebugInfoModal(host) {
  class Ng35DebugInfoModal extends host.ButtonModal {
    constructor(app) {
      super(app);
      this.modalEl.addClass("mod-lg");
      this.titleEl.setText(host.i18n.interface.labelDebugInfo());
      this.infoTextEl = this.contentEl.createEl("textarea", { cls: "debug-textarea" });
      this.infoTextEl.setAttribute("spellcheck", "false");
      this.infoTextEl.disabled = true;
      this.infoTextEl.value = "Loading...";
      const i18n = host.i18n.interface;
      this.addButton("mod-secondary", i18n.labelCopy(), () => {
        env().Ec(this.infoTextEl.value);
        new (env().fb)(i18n.copied({ item: i18n.labelDebugInfo() }));
      });
      if (env().Yl.isDesktop && env().Yl.isDesktopApp) {
        this.addButton("", i18n.helpScreen.labelSandboxVault(), () => {
          env().Of((e) => e.ipcRenderer.sendSync("sandbox"));
        });
      }
      this.addButton("mod-cancel", host.i18n.dialogue.buttonDone(), () => {});
      this.setInfoText();
    }

    async setInfoText() {
      const app = this.app;
      let text = await s05SystemInfo();
      text += "\tLive preview: " + (app.vault.getConfig("livePreview") ? "on" : "off") + "\n";
      if (env().activeDocument.body.classList.contains("emulate-mobile")) {
        text += "\tEmulate mobile: on\n";
      }
      const theme = app.vault.getConfig("theme");
      text += "\tBase theme: " + (theme === "system" ? "adapt to system" : theme === "basalt" ? "dark" : "light") + "\n";
      const customCss = app.customCss || {};
      const themeName = customCss.theme || "none";
      const themeInfo = customCss.themes && customCss.themes[themeName];
      text += "\tCommunity theme: " + themeName + (themeInfo && themeInfo.version ? " " + themeInfo.version : "") + "\n";
      const snippetCount = ng35SnippetCount(customCss);
      text += "\tSnippets enabled: " + snippetCount + "\n";
      const pluginsOn = app.plugins.isEnabled();
      text += "\tRestricted mode: " + (pluginsOn ? "off" : "on") + "\n";
      let pluginCount = 0;
      if (pluginsOn) {
        const manifests = app.plugins.manifests || {};
        const instances = app.plugins.plugins || {};
        text += "\tPlugins installed: " + Object.keys(manifests).length + "\n";
        const ids = Object.keys(instances);
        text += "\tPlugins enabled: " + ids.length + "\n";
        ids.forEach((id, i) => {
          const m = instances[id].manifest || {};
          text += "\t\t" + (i + 1) + ": " + (m.name || id) + " v" + (m.version || "") + "\n";
        });
        pluginCount = ids.length;
      }
      const recs = [];
      if (env().Yl.isDesktopApp && isOlderVersion(env().zf, env().yte)) {
        recs.push(NG35_REC_INSTALLER + s04ProjectUrl() + NG35_REC_INSTALLER_TAIL);
      }
      if (themeName !== "none" || snippetCount > 0) recs.push(NG35_REC_THEME);
      if (pluginsOn && pluginCount > 0) recs.push(NG35_REC_PLUGINS);
      text += "\nRECOMMENDATIONS:\n";
      text += recs.length ? recs.join("") : "\tnone\n";
      this.infoTextEl.value = text;
    }
  }
  return Ng35DebugInfoModal;
}

