    const ratio = imgEl.clientHeight && imgEl.clientWidth ? imgEl.clientHeight / imgEl.clientWidth : 0;
    const maxW = editor.contentDOM && editor.contentDOM.offsetWidth ? editor.contentDOM.offsetWidth : 800;
