// ---- n-g38-publishmodal.js ----
// g38 clean-room: publish "Review changes" modal (spec g38 Part 5).
// Hosts eleven lazily-resolved section classes, the error banner, the loader,
// section switching, and the publish API calls for site/share deletion.

// [instanceField, envName] — section classes resolved lazily at construction.
const ng38PubSections = [
  ["offlineSection", "U7"],
  ["noAccountSection", "W7"],
  ["manageSitesSection", "_7"],
  ["siteOptionsSection", "G7"],
  ["siteFiltersSection", "K7"],
  ["reviewChangesSection", "J7"],
  ["uploadProgressSection", "e9"],
  ["editSiteSlugSection", "t9"],
  ["listPasswordSection", "n9"],
  ["addPasswordSection", "i9"],
  ["configureCustomDomainSection", "r9"],
];

function ng38PubShowEl(el) { if (el && typeof el.show === "function") el.show(); else if (el) el.style.display = ""; }
function ng38PubHideEl(el) { if (el && typeof el.hide === "function") el.hide(); else if (el) el.style.display = "none"; }
function ng38PubSetTitle(el, text) { if (el && typeof el.setText === "function") el.setText(text); else if (el) el.textContent = text; }

function ng38PublishChangesModal(host) {
  function PublishChangesModal(app, plugin) {
    const self = host.Modal.call(this, app) || this;
    self.plugin = plugin;
    self.modalEl.classList.add("mod-publish", "mod-lg", "mod-scrollable-content");
    ng38PubSetTitle(self.titleEl, host.i18n.plugins.publish.actionPublishChanges());
    const doc = self.contentEl.ownerDocument || document;
    for (const [field, name] of ng38PubSections) {
      self[field] = new (env()[name])(self);
    }
    const mc = doc.createElement("div");
    mc.className = "message-container";
    self.contentEl.appendChild(mc);
    self.errorMessageEl = doc.createElement("div");
    self.errorMessageEl.className = "message mod-error";
    self.errorMessageEl.style.display = "none";
    mc.appendChild(self.errorMessageEl);
    self.loaderEl = env().dD(self.contentEl);
    ng38PubHideEl(self.loaderEl);
    self.currentSection = null;
    self.autoLoadSection = null;
    return self;
  }
  inherit(PublishChangesModal, host.Modal);

  PublishChangesModal.prototype.handleError = function (error) {
    console.error(error);
    ng38PubHideEl(this.loaderEl);
    const i18n = host.i18n.plugins.publish;
    if (error instanceof env().p9) {
      if (error.code === "AUTHFAIL") {
        this.openSection(this.manageSitesSection);
        this.showError(i18n.msgNoPermissionToPublishToSite());
      } else if (error.code === "NET") {
        this.showError(i18n.msgNetworkError() + error.message);
      } else {
        this.showError(error.message);
      }
    } else {
      this.showError(i18n.msgSomethingWentWrong() + " " + (error.message || error.toString()));
    }
  };

  PublishChangesModal.prototype.showError = function (message) {
    this.errorMessageEl.textContent = message;
    ng38PubShowEl(this.errorMessageEl);
  };

  PublishChangesModal.prototype.hideError = function () {
    ng38PubHideEl(this.errorMessageEl);
  };

  PublishChangesModal.prototype.onOpen = async function () {
    if (host.Modal.prototype.onOpen) host.Modal.prototype.onOpen.call(this);
    this.closeSection();
    ng38PubShowEl(this.loaderEl);
    if (!env().Hw.token) {
      try {
        await env().Sw(env().Hw);
      } catch (e) {
        ng38PubHideEl(this.loaderEl);
        if (e && e.message === "Not logged in") await this.openSection(this.noAccountSection);
        else await this.openSection(this.offlineSection);
        return;
      }
    }
    if (this.plugin.siteId) {
      let section = this.autoLoadSection;
      this.autoLoadSection = null;
      if (typeof section === "function") section = section();
      if (section) await this.openSection(section);
      else await this.openReviewChanges();
    } else {
      await this.openSection(this.manageSitesSection);
    }
  };

  PublishChangesModal.prototype.onClose = function () {};

  PublishChangesModal.prototype.autoLoad = function (section) {
    this.autoLoadSection = section;
    return this;
  };

  PublishChangesModal.prototype.deleteSite = async function (siteId) {
    await env().Nw(env().Hw.token, siteId);
    if (this.plugin.siteId === siteId) await this.plugin.setup(null, null);
    await this.openSection(this.manageSitesSection);
  };

  PublishChangesModal.prototype.deleteSiteShare = async function (siteId, shareId) {
    await env().Bw(env().Hw.token, siteId, shareId);
    if (this.plugin.siteId === siteId) await this.plugin.setup(null, null);
    await this.openSection(this.manageSitesSection);
  };

  PublishChangesModal.prototype.acceptSiteShare = async function (siteId, code) {
    await env().gw("/publish/share/accept", { token: env().Hw.token, code });
    if (this.plugin.siteId === siteId) await this.plugin.setup(null, null);
    await this.openSection(this.manageSitesSection);
  };

  PublishChangesModal.prototype.openReviewChanges = function () {
    return this.openSection(this.reviewChangesSection);
  };

  PublishChangesModal.prototype.openManageSites = function () {
    return this.openSection(this.manageSitesSection);
  };

  PublishChangesModal.prototype.editSlug = async function (site, slug) {
    this.editSiteSlugSection.setSiteInfo(site);
    this.editSiteSlugSection.setExistingSlug(slug);
    await this.openSection(this.editSiteSlugSection);
  };

  PublishChangesModal.prototype.uploadChanges = async function (changes) {
    this.uploadProgressSection.addChanges(changes);
    await this.openSection(this.uploadProgressSection);
  };

  PublishChangesModal.prototype.showPasswords = async function () {
    const section = this.listPasswordSection;
    if (this.currentSection) this.currentSection.hide();
    ng38PubShowEl(this.loaderEl);
    try {
      const passwords = (await this.plugin.apiGetPassword()).pass;
      section.setPasswords(passwords);
      section.updateDisplay();
      await this.openSection(section);
    } catch (e) {
      this.handleError(e);
    }
  };

  PublishChangesModal.prototype.openAddPassword = function () {
    return this.openSection(this.addPasswordSection);
  };

  PublishChangesModal.prototype.setTitleText = function (text) {
    ng38PubSetTitle(this.titleEl, text);
  };

  PublishChangesModal.prototype.closeSection = function () {
    this.hideError();
    if (this.currentSection) {
      this.currentSection.hide();
      this.currentSection = null;
    }
  };

  PublishChangesModal.prototype.openSection = async function (section) {
    this.closeSection();
    if (section.title) this.setTitleText(section.title);
    this.currentSection = section;
    ng38PubShowEl(this.loaderEl);
    await section.show();
    ng38PubHideEl(this.loaderEl);
  };

  return PublishChangesModal;
}

// Test-facing alias for the legacy module contract.

// ---- n-g38-startup.js ----
// g38 clean-room: "Startup time" diagnostic modal + StartupStat rows (spec g38 Part 6).
// Timings come from the shared animation-name tree env().lD; locale via env().sm().

let ng38StatClass = null;
function ng38Stat() {
  if (!ng38StatClass) ng38StatClass = ng38StartupStat();
  return ng38StatClass;
}

function ng38AnimNode(path) {
  let node = env().lD;
  if (path) {
    for (const seg of path.split(".")) {
      if (!node || !node.children || !Object.prototype.hasOwnProperty.call(node.children, seg)) return null;
      node = node.children[seg];
    }
  }
  return node || null;
}

function ng38AnimDuration(path) {
  const node = ng38AnimNode(path);
  return node && node.duration != null ? node.duration : 0;
}

function ng38Fmt() {
  return new Intl.NumberFormat(env().sm(), { maximumFractionDigits: 0 });
}

function ng38Ms(ms) {
  return ng38Fmt().format(ms) + "ms";
}

function ng38HideEl(el) {
  if (el && typeof el.hide === "function") el.hide();
  else if (el) el.style.display = "none";
}

function ng38StartupStat() {
  function StartupStat(containerEl) {
    const doc = containerEl.ownerDocument || document;
    this.containerEl = doc.createElement("div");
    this.containerEl.className = "startup-stat";
    containerEl.appendChild(this.containerEl);
    this.infoEl = doc.createElement("div");
    this.infoEl.className = "startup-info";
    this.containerEl.appendChild(this.infoEl);
  }
  StartupStat.prototype.setHeading = function (heading) {
    this.containerEl.classList.toggle("mod-heading", !!heading);
    return this;
  };
  StartupStat.prototype.addLabel = function (text) {
    const el = document.createElement("span");
    el.className = "startup-label";
    el.textContent = text;
    this.infoEl.appendChild(el);
    return this;
  };
  StartupStat.prototype.addDesc = function (text) {
    const el = document.createElement("span");
    el.className = "startup-desc";
    el.textContent = text == null ? "" : text;
    this.infoEl.appendChild(el);
    return this;
  };
  StartupStat.prototype.addValue = function (text) {
    const el = document.createElement("div");
    el.className = "startup-value";
    el.textContent = text;
    this.containerEl.appendChild(el);
    return this;
  };
  return StartupStat;
}

function ng38CommunityRows(app) {
  const node = ng38AnimNode("communityPlugins");
  if (!node) return null;
  const children = Object.values(node.children || {})
    .slice()
    .sort((a, b) => (b.duration || 0) - (a.duration || 0));
  return children.map((child) => {
    const manifest = app.plugins.manifests[child.key];
    return {
      id: child.key,
      label: manifest ? manifest.name : child.key,
      desc: manifest ? manifest.version || "" : "",
      time: child.duration || 0,
    };
  });
}

// Exact clipboard summary.
function ng38StartupSummary(app, host) {
  const platform = host.Platform;
  const fmt = ng38Fmt();
  const lines = ["Basalt start-up time breakdown", ""];
  if (platform.isDesktopApp) {
    lines.push(`Basalt version: ${platform.version}`);
    lines.push(`Installer version: ${platform.build}`);
    lines.push(`Operating system: ${platform.osName} ${platform.osVersion}`);
  } else if (platform.isMobileApp) {
    lines.push(`Basalt version: ${platform.version} (${platform.build})`);
    lines.push(`API version: ${s16ApiVersion}`);
    lines.push(`Operating system: ${platform.osName} ${platform.osVersion} (${platform.manufacturer} ${platform.model})`);
    if (platform.isAndroidApp) lines.push(`Webview version: ${chromeVersion(navigator.userAgent)}`);
  }
  lines.push("");
  lines.push(`- Total startup time: ${ng38Ms(ng38AnimDuration(""))}`);
  lines.push(`- Initialization: ${ng38Ms(ng38AnimDuration("initialization"))}`);
  const icloud = ng38AnimDuration("icloud");
  if (icloud) lines.push(`- iCloud: ${ng38Ms(icloud)}`);
  const fileCount = app.vault.getRoot().getFileCount();
  lines.push(`- Vault (${fmt.format(fileCount)} files): ${ng38Ms(ng38AnimDuration("vault"))}`);
  const stats = env().sD || { views: 0, deferredViews: 0 };
  lines.push(`- Workspace (${stats.views} tabs, ${stats.deferredViews} deferred): ${ng38Ms(ng38AnimDuration("workspace"))}`);
  lines.push(`- Core plugins: ${ng38Ms(ng38AnimDuration("corePlugins"))}`);
  const rows = ng38CommunityRows(app);
  if (rows) {
    lines.push(`- Community plugins (${fmt.format(Object.keys(app.plugins.plugins).length)} active): ${ng38Ms(ng38AnimDuration("communityPlugins"))}`);
    for (const row of rows) lines.push(`  - ${row.label} (${row.desc}): ${ng38Ms(row.time)}`);
  }
  return lines.join("\n");
}

function ng38StartupModal(host) {
  function StartupModal(app) {
    const self = host.DialogModal.call(this, app) || this;
    self.app = app;
    self.modalEl.classList.add("mod-lg", "mod-scrollable-content", "mod-plugin-debug");
    if (typeof self.setTitle === "function") self.setTitle("Startup time");
    const doc = self.contentEl.ownerDocument || document;
    const platform = host.Platform;
    const i18n = host.i18n;
    const Stat = ng38Stat();

    const mkList = (cls) => {
      const list = doc.createElement("div");
      list.className = cls;
      self.contentEl.appendChild(list);
      return list;
    };
    const mkRow = (parent, label) => new Stat(parent).addLabel(label);

    const info = mkList("startup-stat-list");
    const device = mkRow(info, "Device");
    const os = mkRow(info, "Operating system");
    const basalt = mkRow(info, "Basalt");
    const osValue = `${platform.osName} ${platform.osVersion}`;
    if (platform.isMobileApp) {
      device.addValue(`${platform.manufacturer} ${platform.model}`);
      os.addValue(osValue);
      basalt.addDesc(platform.version);
      basalt.addLabel("Build").addDesc(platform.build);
    } else if (platform.isDesktopApp) {
      ng38HideEl(device.containerEl);
      os.addValue(osValue);
      basalt.addDesc(platform.version);
      basalt.addLabel("Installer").addDesc(platform.build);
    }

    const timed = mkList("startup-timing-list");
    new Stat(timed).setHeading(true).addLabel("Total app startup").addValue(ng38Ms(ng38AnimDuration("")));
    mkRow(timed, "Initialization").addValue(ng38Ms(ng38AnimDuration("initialization")));
    mkRow(timed, "Vault")
      .addDesc(i18n.nouns.fileWithCount({ count: app.vault.getRoot().getFileCount() }))
      .addValue(ng38Ms(ng38AnimDuration("vault")));
    const wsStats = env().sD || { views: 0, deferredViews: 0 };
    mkRow(timed, "Workspace")
      .addDesc(`${wsStats.views} tabs (${wsStats.deferredViews} deferred)`)
      .addValue(ng38Ms(ng38AnimDuration("workspace")));
    mkRow(timed, "Core plugins")
      .addDesc(i18n.nouns.pluginActiveWithCount({ count: app.internalPlugins.getEnabledPlugins().length }))
      .addValue(ng38Ms(ng38AnimDuration("corePlugins")));

    const commRows = ng38CommunityRows(app);
    if (commRows) {
      const commList = mkList("startup-timing-list");
      new Stat(commList)
        .setHeading(true)
        .addLabel("Community plugins")
        .addDesc(i18n.nouns.pluginActiveWithCount({ count: Object.keys(app.plugins.plugins).length }))
        .addValue(ng38Ms(ng38AnimDuration("communityPlugins")));
      for (const row of commRows) {
        mkRow(commList, row.label).addDesc(row.desc).addValue(ng38Ms(row.time));
      }
    }

    self.addButton("mod-secondary", i18n.interface.labelCopy(), async () => {
      await navigator.clipboard.writeText(ng38StartupSummary(app, host));
      new host.Notice(i18n.interface.copied({ context: "generic" }));
      return true;
    });
    self.addButton("mod-cancel", i18n.dialogue.buttonDone(), () => {});
    return self;
  }
  inherit(StartupModal, host.DialogModal);
  return StartupModal;
}

