  let to = range.to;

  host.cmFormatSeek(cursor, from);
  for (;;) {
    const node = cursor.node;
    if (!node || !isMarkNode(node)) break;
    const inner = ng39FormatInnerMark(state, cursor.from, mark, 1);
    if (inner) from = cursor.from;
    if (!cursor.prevSibling()) break;
  }

